"""Temp-target tests for the skill registration rite."""

import json
from pathlib import Path

import sync_skills as sync_skills


def _snapshot(root: Path) -> dict[str, str]:
    return {
        path.relative_to(root).as_posix(): path.read_text(encoding="utf-8")
        for path in sorted(root.rglob("*"))
        if path.is_file()
    }


def _generated_comment(source_dir: Path) -> str:
    return (
        f"<!-- GENERATED - source: {source_dir}/SKILL.md | "
        "DO NOT EDIT this file. Edit the source and run /grm-update skills. -->"
    )


def _legacy_generated_comment(source_dir: Path) -> str:
    # A generated-provenance comment in the em-dash separator form, carrying no
    # FRAMEWORK_SKILL_OWNERSHIP marker.
    return (
        f"<!-- GENERATED — source: {source_dir}/SKILL.md | "
        "DO NOT EDIT this file. Edit the source and run /grm-update. -->"
    )


def test_sync_skills_dry_run_plans_without_writing(tmp_path, monkeypatch, capsys):
    target = tmp_path / "codex" / "skills"
    # A managed-prefix dir not in the catalog is planned for cleanup, not preserved.
    existing = target / "grm-dev-existing"
    existing.mkdir(parents=True)
    (existing / "SKILL.md").write_text("stale, no marker\n", encoding="utf-8", newline="\n")
    monkeypatch.setattr(sync_skills, "LOCAL_LIBRARY", tmp_path / "missing-library.json")

    result = sync_skills.register_target(
        "codex",
        {
            "label": "Codex Test",
            "path": target,
            "pointer_only": True,
        },
        dry_run=True,
    )

    output = capsys.readouterr().out
    assert result["mode"] == "plan"
    assert result["registered"] > 0
    assert "Would create" in output
    assert "Would clean stale: /grm-dev-existing" in output
    # Plan mode writes nothing.
    assert (existing / "SKILL.md").read_text(encoding="utf-8") == "stale, no marker\n"
    assert not (target / "grm-dev-validate").exists()


def test_sync_skills_apply_is_idempotent_for_pointer_target(tmp_path, monkeypatch):
    target = tmp_path / "codex" / "skills"
    monkeypatch.setattr(sync_skills, "LOCAL_LIBRARY", tmp_path / "missing-library.json")
    config = {
        "label": "Codex Test",
        "path": target,
        "pointer_only": True,
    }

    first = sync_skills.register_target("codex", config, dry_run=False)
    first_snapshot = _snapshot(target)
    second = sync_skills.register_target("codex", config, dry_run=False)
    second_snapshot = _snapshot(target)

    assert first["mode"] == "apply"
    assert second["mode"] == "apply"
    assert first["registered"] == second["registered"]
    assert first_snapshot == second_snapshot
    assert (target / "grm-dev-validate" / "SKILL.md").is_file()
    assert "FRAMEWORK_SKILL_OWNERSHIP" in (target / "grm-dev-validate" / "SKILL.md").read_text(encoding="utf-8")
    assert all(path.name == "SKILL.md" for path in target.rglob("*") if path.is_file())


def test_sync_skills_apply_leaves_no_staging_dir(tmp_path, monkeypatch):
    target = tmp_path / "codex" / "skills"
    monkeypatch.setattr(sync_skills, "LOCAL_LIBRARY", tmp_path / "missing-library.json")

    sync_skills.register_target(
        "codex",
        {"label": "Codex Test", "path": target, "pointer_only": True},
        dry_run=False,
    )

    assert (target / "grm-dev-validate" / "SKILL.md").is_file()
    assert list(target.glob("*.tmp")) == []  # staging is swapped in, never left behind


def test_sync_skills_overwrites_unmarked_managed_dir(tmp_path, monkeypatch):
    # A directory under a managed prefix with no ownership marker is the framework's to
    # replace - re-registering overwrites it with the current source, never blocks.
    target = tmp_path / "codex" / "skills"
    existing = target / "grm-dev-validate"
    existing.mkdir(parents=True)
    (existing / "SKILL.md").write_text("stale, no marker\n", encoding="utf-8", newline="\n")
    monkeypatch.setattr(sync_skills, "LOCAL_LIBRARY", tmp_path / "missing-library.json")

    result = sync_skills.register_target(
        "codex",
        {"label": "Codex Test", "path": target, "pointer_only": True},
        dry_run=False,
    )

    assert result["blocked"] == 0
    content = (existing / "SKILL.md").read_text(encoding="utf-8")
    assert "stale, no marker" not in content
    assert "FRAMEWORK_SKILL_OWNERSHIP" in content


def test_sync_skills_reset_managed_replaces_unmarked_and_keeps_outside_namespace(tmp_path, monkeypatch):
    target = tmp_path / "codex" / "skills"
    existing = target / "grm-dev-validate"
    existing.mkdir(parents=True)
    (existing / "SKILL.md").write_text("stale, no marker\n", encoding="utf-8", newline="\n")
    outside_namespace = target / "personal-tool"  # NOT a managed prefix
    outside_namespace.mkdir()
    (outside_namespace / "SKILL.md").write_text("keep me\n", encoding="utf-8", newline="\n")
    monkeypatch.setattr(sync_skills, "LOCAL_LIBRARY", tmp_path / "missing-library.json")

    result = sync_skills.register_target(
        "codex",
        {"label": "Codex Test", "path": target, "pointer_only": True},
        dry_run=False,
        reset_managed=True,
    )

    # The unmarked managed-prefix dir is reset and re-registered; a directory
    # outside any managed prefix is never touched.
    assert result["reset"] >= 1
    assert result["blocked"] == 0
    assert "FRAMEWORK_SKILL_OWNERSHIP" in (existing / "SKILL.md").read_text(encoding="utf-8")
    assert (outside_namespace / "SKILL.md").read_text(encoding="utf-8") == "keep me\n"


def test_reset_managed_skill_dirs_removes_all_managed(tmp_path):
    skills_target = tmp_path / "skills"

    unmarked = skills_target / "grm-dev-mycustom"
    unmarked.mkdir(parents=True)
    (unmarked / "SKILL.md").write_text("hand-authored, no marker\n", encoding="utf-8", newline="\n")

    marked = skills_target / "grm-dev-stale"
    marked.mkdir()
    marker = sync_skills.ownership_comment({
        "schema_version": sync_skills.OWNERSHIP_SCHEMA_VERSION,
        "generation": sync_skills.REGISTER_GENERATION,
        "registered_by": "framework",
        "command": "/grm-dev-stale",
    })
    (marked / "SKILL.md").write_text(f"---\nname: grm-dev-stale\n---\n{marker}\n", encoding="utf-8", newline="\n")

    outside = skills_target / "personal-tool"  # not a managed prefix
    outside.mkdir()
    (outside / "SKILL.md").write_text("keep me\n", encoding="utf-8", newline="\n")

    removed = sync_skills.reset_managed_skill_dirs(skills_target, ("grm-",), dry_run=False)

    # Both managed-prefix dirs are removed regardless of ownership; the
    # outside-namespace dir is left alone.
    assert removed == 2
    assert not marked.exists()
    assert not unmarked.exists()
    assert outside.exists()


def test_sync_skills_reset_managed_dry_run_does_not_write(tmp_path, monkeypatch, capsys):
    target = tmp_path / "codex" / "skills"
    owned = target / "grm-dev-validate"
    owned.mkdir(parents=True)
    marker = sync_skills.ownership_comment({
        "schema_version": sync_skills.OWNERSHIP_SCHEMA_VERSION,
        "generation": sync_skills.REGISTER_GENERATION,
        "registered_by": "framework",
        "command": "/grm-dev-validate",
    })
    (owned / "SKILL.md").write_text(
        f"---\nname: grm-dev-validate\n---\n{marker}\nowned body\n", encoding="utf-8", newline="\n"
    )
    monkeypatch.setattr(sync_skills, "LOCAL_LIBRARY", tmp_path / "missing-library.json")

    result = sync_skills.register_target(
        "codex",
        {
            "label": "Codex Test",
            "path": target,
            "pointer_only": True,
        },
        dry_run=True,
        reset_managed=True,
    )

    output = capsys.readouterr().out
    assert result["mode"] == "plan"
    assert result["blocked"] == 0
    assert result["reset"] == 1
    assert "Would reset managed namespace: /grm-dev-validate" in output
    assert "Would create: /grm-dev-validate" in output
    assert (owned / "SKILL.md").read_text(encoding="utf-8").endswith("owned body\n")


def test_sync_skills_overwrites_marker_less_generated_skill(tmp_path, monkeypatch):
    # A generated skill carrying the provenance comment but no ownership marker is
    # still overwritten - cleanup/overwrite is decided by managed-prefix membership.
    target = tmp_path / "codex" / "skills"
    existing = target / "grm-dev-validate"
    existing.mkdir(parents=True)
    source_dir = sync_skills.FRAMEWORK_PATH / "skills" / "dev" / "validate"
    (existing / "SKILL.md").write_text(
        "---\nname: grm-dev-validate\n---\n"
        f"{_generated_comment(source_dir)}\n"
        "old generated body\n",
        encoding="utf-8",
        newline="\n",
    )
    monkeypatch.setattr(sync_skills, "LOCAL_LIBRARY", tmp_path / "missing-library.json")

    result = sync_skills.register_target(
        "codex",
        {
            "label": "Codex Test",
            "path": target,
            "pointer_only": True,
        },
        dry_run=False,
    )

    content = (existing / "SKILL.md").read_text(encoding="utf-8")
    assert result["blocked"] == 0
    assert "FRAMEWORK_SKILL_OWNERSHIP" in content
    assert "old generated body" not in content


